{"implementation":"def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    by_id = {node["id"]: node for node in nodes}
    retained = set()

    for node in nodes:
        if not node["removable"] or node["symbol"] in required_symbols:
            retained.add(node["id"])

    changed = True
    while changed:
        changed = False
        for node in nodes:
            if node["id"] in retained:
                parent = node["parent"]
                if parent in by_id and parent not in retained:
                    retained.add(parent)
                    changed = True

    removed_node_ids = [node["id"] for node in nodes if node["id"] not in retained]
    retained_node_ids = [node["id"] for node in nodes if node["id"] in retained]
    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }
"}
